import type { NextConfig } from "next";
import { createRequire } from "module";

const require = createRequire(import.meta.url);
const withBundleAnalyzer = require("@next/bundle-analyzer")({
  enabled: process.env.ANALYZE === "true",
});

// In dev, run Velite in watch mode so content edits hot-reload.
// For `build`, content is generated by the `velite` step in the build script
// (running it here races webpack and can wipe .velite mid-compile).
const isDev = process.argv.includes("dev");
if (isDev && !process.env.VELITE_STARTED) {
  process.env.VELITE_STARTED = "1";
  import("velite").then(({ build }) => build({ watch: true, clean: false }));
}

/**
 * Content-Security-Policy — shipped as Report-Only first (observe, don't break), to be
 * promoted to enforced (`Content-Security-Policy`) once a live check shows zero
 * violations. Scoped to the site's REAL surfaces (all verified against the code):
 *  - connect-src: 'self' covers every /api/* route (chat, tts, transcribe — Bedrock/
 *    Polly/Transcribe are called SERVER-side, so the browser never connects to AWS).
 *    Vercel analytics/insights endpoints added for the injected beacons.
 *    wss://speech.googleapis.com + wss://speech.platform.bing.com: browser Web Speech
 *    API (SpeechRecognition) opens a cross-origin WebSocket on Chrome/Edge respectively;
 *    subject to connect-src since Chrome 63 — without these two, the STT loop fails with
 *    network error on every attempt and voice is permanently broken in production.
 *    https://www.gstatic.com: Chrome's online SpeechSynthesis voices stream from here.
 *  - script/style 'unsafe-inline': Next inline bootstrap + the inlineCss experiment +
 *    R3F/Vercel inline. (No auth/secrets on this site, so the residual XSS surface is
 *    low; rehype-sanitize + skipHtml already neutralize chat markdown.)
 *  - img/media 'self' data: blob:: WebGL textures (data:) and the Polly <audio> blob:
 *    URL (URL.createObjectURL in use-speech-synthesis.ts).
 *  - frame-ancestors 'none': clickjacking defense (pairs with X-Frame-Options: DENY).
 */
const csp = [
  "default-src 'self'",
  "base-uri 'self'",
  "object-src 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
  // 'unsafe-eval' is required in BOTH dev AND production: MDXContent uses `new Function(code)`
  // to evaluate Velite-generated MDX function-body strings in the browser at runtime. The
  // comment previously claimed Velite pre-compiles MDX at build time — this was incorrect.
  // Velite outputs a serialized `code` string; MDXContent deserialises it via `new Function`
  // client-side on EVERY page with MDX body content (projects, work, notes). Removing
  // 'unsafe-eval' crashes all project/work/note pages with a React render-error boundary.
  // This site has no auth, no untrusted user input, and rehype-sanitize guards chat markdown —
  // so the eval surface is limited to author-controlled MDX. Accepted risk, same as 'unsafe-inline'.
  `script-src 'self' 'unsafe-inline' 'unsafe-eval' 'wasm-unsafe-eval' https://va.vercel-scripts.com https://vercel.live`,
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' data: blob: https://img.shields.io",
  "media-src 'self' blob:",
  "font-src 'self' data:",
  // wss://speech.googleapis.com — Chrome/Chromium-based Edge Web Speech API (SpeechRecognition
  // opens a WebSocket to Google's cloud; subject to connect-src in Chrome 63+). Without this,
  // every recognition attempt fails with onerror.error="network", sending the voice loop to
  // "paused" immediately. Safari uses on-device processing (no external connect); Firefox
  // disables the API by default. The Playwright zero-violation audit never exercised live mic
  // input, so this was invisible until the CSP was enforced in production.
  // wss://speech.platform.bing.com — Edge on Windows uses Microsoft's speech service instead
  // of Google's; same WebSocket model, different host.
  // https://www.gstatic.com — Chrome's browser SpeechSynthesis online voices (e.g. "Google US
  // English") stream from gstatic. Without this they fall back to local voices (lower quality
  // but non-breaking); included here so neural voices work in talk mode.
  "connect-src 'self' https://*.vercel-insights.com https://vitals.vercel-insights.com https://va.vercel-scripts.com wss://speech.googleapis.com wss://speech.platform.bing.com https://www.gstatic.com",
  "worker-src 'self' blob:",
  "manifest-src 'self'",
  // Vercel-only. `process.env.VERCEL` is set exclusively by Vercel's own infrastructure
  // (Preview and Production) — never locally via `next dev` or `next start`, even in
  // production mode. This directive upgrades every HTTP sub-resource request on the page
  // to HTTPS, which is correct and desired on Vercel (always served over TLS). Locally
  // the app is plain HTTP with no TLS listener, and unlike Chromium — which special-cases
  // `localhost` as an already-secure context and quietly ignores the directive there —
  // WebKit obeys it literally, rewriting every script/font/manifest request to
  // https://localhost:PORT, which fails outright (no TLS listener). Net effect: on WebKit
  // specifically, zero client JS ever loads locally — no hydration, no click handlers, no
  // `?view=` query-param sync — which looked exactly like dozens of unrelated app bugs
  // (clicks doing nothing, deep-links never applying) until this session's mobile-safari
  // Playwright project's very first real run traced every one of them to this one header.
  // Gating on VERCEL keeps production's security posture byte-for-byte identical while
  // making local WebKit/Safari e2e testing possible at all.
  ...(process.env.VERCEL ? ["upgrade-insecure-requests"] : []),
].join("; ");

// Static security headers applied to every route. HSTS is already set by Vercel's
// platform default, so it is intentionally omitted here (avoids a weaker duplicate).
const securityHeaders = [
  { key: "X-Frame-Options", value: "DENY" },
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  // No OAuth popups or cross-origin postMessage flows on this auth-less site, so
  // same-origin isolation costs nothing. External links already open with
  // noopener,noreferrer (command-palette, article cards), so they never relied on
  // window.opener access that COOP would otherwise take away.
  { key: "Cross-Origin-Opener-Policy", value: "same-origin" },
  { key: "Cross-Origin-Resource-Policy", value: "same-origin" },
  // Voice requests the mic — scope it to same-origin and deny camera/geo/etc.
  {
    key: "Permissions-Policy",
    value: "microphone=(self), camera=(), geolocation=(), browsing-topics=()",
  },
  // ENFORCED. Shipped Report-Only in v1.4.0; a live Playwright sweep across all four
  // views (incl. the WebGL Play view) logged ZERO violations, and a per-directive
  // audit against the real resource loads (scripts/styles/fonts/img/media/connect/
  // worker — including the Polly-audio blob: and AWS paths the sweep didn't exercise)
  // confirmed every browser-loadable resource is covered. The policy string is
  // unchanged from the Report-Only version — only the header key flips to enforce, so
  // the proven-safe baseline is exactly what's now blocking. `upgrade-insecure-requests`
  // is retained (it becomes meaningful once enforced). `'unsafe-inline'` on script/
  // style is intentional + unavoidable (Next inline bootstrap + inlineCss + Motion
  // runtime style attributes, which nonces can't cover) — accepted on an auth-less site.
  { key: "Content-Security-Policy", value: csp },
];

const nextConfig: NextConfig = {
  // Pin the workspace root to this project (multiple lockfiles exist on the machine).
  turbopack: { root: __dirname },
  // Build-time constants inlined into the client bundle.
  // NEXT_PUBLIC_BUILD_YEAR exists because the footer copyright year must be a STABLE value:
  // under nextConfig.cacheComponents, calling `new Date()` during render fails the prerender
  // ("encountered the unstable value `new Date()` in a Client Component") and that error cannot
  // be deferred with `instant = false`. Computing it HERE runs in the Node config at build time,
  // never during prerender, so it is a plain literal by the time the footer renders — and it
  // still refreshes on every deploy, so it never goes stale in practice.
  env: { NEXT_PUBLIC_BUILD_YEAR: String(new Date().getFullYear()) },
  // Inline critical CSS into <head> to cut a render-blocking stylesheet request —
  // Tailwind v4 is the exact use case this flag targets. Kept only if a before/after
  // Lighthouse on the deployed URL shows an FCP/LCP win without a TTFB regression.
  experimental: {
    inlineCss: true,
    // NOTE: `viewTransition: true` was REMOVED here in the 16.3.0 upgrade. It no longer exists in
    // Next's ExperimentalConfig (absent from both config-schema.js and the types), so leaving it
    // was a hard typecheck failure. Per the installed 16.3 guide
    // (node_modules/next/dist/docs/01-app/02-guides/view-transitions.md): "View transitions work in
    // the App Router with no configuration" — the flag graduated to always-on rather than being cut.
    //
    // Removing it is a no-op for THIS app regardless: the flag gated React's <ViewTransition>
    // component, which this codebase never adopted. Our four-view transition is the NATIVE
    // document.startViewTransition + ::view-transition-* CSS path (src/components/view-context.tsx
    // :106-115, src/app/globals.css:263-299). The previous comment claimed this flag drove
    // "directional slide animations on project card links via transitionTypes" — inaccurate:
    // `transitionTypes` appears nowhere in src/, and the only "ViewTransition" identifier in the
    // codebase is an unrelated local skeleton component (ui/skeleton.tsx:102 SkeletonViewTransition).
    // Tree-shake icon/animation imports at module level — reduces first-load JS.
    // NOTE: three, @react-three/fiber, @react-three/drei are intentionally excluded.
    // The C-3 investigation (commit 6246ed9) confirmed this flag does NOT collapse
    // the R3F twin-chunk in Turbopack; the Option B barrel (src/lib/r3f.ts, commit
    // f7c5110) is the correct fix and is already live. Re-adding these packages
    // would re-introduce the disproven optimization against the live barrel.
    //
    // R3F TWIN-CHUNK: RESOLVED by the 16.3.0 upgrade itself — measured, not assumed.
    // This was recorded for months as "upstream blocked, needs a turbopack chunk config API".
    // It is now fixed with NO experimental flags. Clean-build measurements (`rm -rf .next`,
    // `pnpm build`, exit 0), counting chunks that contain `react-three`/`THREE.`:
    //   16.2.9 → 876 + 876 + 256 + 20 + 8 = 2036 KB across 5 chunks (TWO 876 KB copies)
    //   16.3.0 → 876 +       256 + 20 + 8 = 1160 KB across 4 chunks (ONE 876 KB copy)
    //   delta  → -876 KB (-43%)
    // Confirmed by symbol count, not just chunk count: the three.js core symbol
    // `WebGLRenderer` now appears in exactly ONE chunk (37 occurrences, all in the single
    // 876 KB chunk). Two chunks still *reference* react-three, but only one carries the core.
    // Reproduced across two independent 16.2.9 builds (both showed 2 copies) and one clean
    // 16.3.0 build.
    //
    // CONSEQUENCE: do NOT adopt `experimental.turbopackChunking` / `turbopackSharedRuntime`
    // for this. The win is already banked, and those flags are doc-labeled "not recommended
    // for production" and `turbopackSharedRuntime` shipped with a hydration-breaking race.
    // The src/lib/r3f.ts barrel stays — it is load-bearing for the single-copy outcome.
    optimizePackageImports: ["lucide-react", "motion"],
    // Cache Components (Next 16's `cacheComponents: true`) — ENABLED. This one key SUPERSEDES the
    // old `experimental.ppr` / `experimental_ppr` / `dynamicIO` / `useCache` opt-ins.
    //
    // This was recorded for months as "upstream blocked, waiting for a per-route escape hatch".
    // That diagnosis was WRONG and no upstream fix was ever needed. The RSC transform
    // (react_server_components.rs, verified at tag v16.2.9) rejects the mere PRESENCE of
    // `export const runtime` — the `"runtime" =>` arm receives only (&export_name, &span) and never
    // inspects `decl.init`, so "nodejs" and "edge" are indistinguishable to it. But `nodejs` is
    // already the DEFAULT and Cache Components *requires* it (only `edge` is unsupported), so those
    // exports were redundant and the remedy was deletion.
    //
    // Migration scope was 26 segment configs across 22 files — NOT the 9 previously claimed.
    // Confirmed empirically: enabling this flag failed the build with exactly `26 errors`.
    //   13x `runtime`     -> deleted (redundant; nodejs is the default)
    //    4x `revalidate`  -> handled per actual data source, not uniformly. /projects awaits a live
    //                        getRepoFeed() so it got `"use cache"` + cacheLife("hours") (that profile
    //                        is { stale: 300, revalidate: 3600, expire: 86400 }, preserving the old
    //                        3600s exactly). /work + /notes are pure build-time Velite data with
    //                        nothing to revalidate against, so theirs were simply deleted.
    //                        api/github/stats already had fetch-level revalidate.
    //    9x `force-dynamic` -> deleted; none were a caching decision. The .md routes read req.url
    //                        (which is what makes them dynamic anyway) and llms-full.txt became
    //                        correctly STATIC.
    // `maxDuration` (11 uses) and `preferredRegion` are NOT rejected — streaming timeouts survive.
    //
    // Two constraints only a real build surfaces, both handled:
    //   1. `generateStaticParams` must return >=1 result — collided with the flag-gated /notes
    //      "ship dark" pattern. Behaviour is unchanged (the page still calls notFound()); those
    //      routes are now prerendered AS 404s. Verified live: /notes/<slug> -> 404.
    //   2. Synchronous IO (`new Date()`, `Date.now()`) fails prerender and CANNOT be deferred with
    //      `instant = false`. Hence NEXT_PUBLIC_BUILD_YEAR above (footer) and
    //      `await connection()` + `instant = false` on /admin/telemetry.
    cacheComponents: true,
  },
  images: {
    formats: ["image/avif", "image/webp"],
    remotePatterns: [
      // github-readme-stats removed: the /projects feed is now first-party
      // (src/lib/github.ts, server-fetched + ISR) — no external <img> embed.
      { protocol: "https", hostname: "img.shields.io" },
    ],
  },
  async headers() {
    // Per-route CSP override for /resume — the PDF iframe needs frame-ancestors 'self'
    // so the browser allows anvilry.vercel.app to embed its own PDF inside the page.
    // The global securityHeaders sets frame-ancestors 'none' (clickjacking defense);
    // we override only X-Frame-Options and the CSP frame-ancestors directive here.
    const resumeHeaders = securityHeaders.map((h) => {
      if (h.key === "X-Frame-Options")
        return { key: h.key, value: "SAMEORIGIN" };
      if (h.key === "Content-Security-Policy") {
        return {
          key: h.key,
          value: h.value.replace(
            "frame-ancestors 'none'",
            "frame-ancestors 'self'",
          ),
        };
      }
      return h;
    });

    return [
      { source: "/:path*", headers: securityHeaders },
      // Override frame-ancestors for the resume route so the PDF iframe works.
      { source: "/resume", headers: resumeHeaders },
      { source: "/resume/:path*", headers: resumeHeaders },
    ];
  },
  async rewrites() {
    // Rewrite /:collection/:slug.md → /api/md/:collection/:slug so that AI crawlers
    // can fetch raw markdown via canonical pretty-URLs (e.g. /work/pensieve.md).
    return [
      { source: "/work/:slug.md", destination: "/api/md/work/:slug" },
      { source: "/projects/:slug.md", destination: "/api/md/projects/:slug" },
      { source: "/articles/:slug.md", destination: "/api/md/articles/:slug" },
      { source: "/notes/:slug.md", destination: "/api/md/notes/:slug" },
    ];
  },
};

export default withBundleAnalyzer(nextConfig);
